edits.oldString:
function pickTargetTestFile(goal: string, changedFiles: string[]): string | null {
  const { existsSync } = require('node:fs');
  // If a changed file has a corresponding .test.ts that EXISTS, run it.
  for (const changed of changedFiles) {
    const testFile = changed.replace(/\.ts$/, '.test.ts');
    if (testFile !== changed) {
      try {
        if (existsSync(path.resolve(DEFAULT_PROJECT_ROOT, testFile))) {
          return testFile;
        }
      } catch {
        // existsSync failed — skip this candidate
      }
    }
  }
  // Default: run the autonomous coder's own tests if they exist
  const defaultTest = 'backend/ivx-autonomous-coder.test.ts';
  try {
    if (existsSync(path.resolve(DEFAULT_PROJECT_ROOT, defaultTest))) {
      return defaultTest;
    }
  } catch {
    // existsSync failed
  }
  // No test file found — return null so caller skips test gate honestly
  return null;
}

